<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;
use App\Models\{StudentProfile,User,Classroom,StudentEnrollment};
use App\Support\CurrentSchool;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Validation\Rule;
class StudentController extends Controller {
 private function authorizeManager(Request $r): void {abort_unless(in_array($r->user()->role,['school_admin','super_admin'],true),403,'ليست لديك صلاحية إدارة الطلاب.');}
 public function index(Request $r){$this->authorizeManager($r);$q=StudentProfile::with(['user:id,name,email,phone,is_active','enrollments.classroom.grade'])->where('school_id',CurrentSchool::id());if($r->filled('search')){$s=$r->string('search');$q->where(fn($x)=>$x->where('student_number','like','%'.$s.'%')->orWhereHas('user',fn($u)=>$u->where('name','like','%'.$s.'%')));}if($r->filled('status'))$q->where('status',$r->string('status'));return $q->orderByDesc('id')->paginate(min((int)$r->input('per_page',20),100));}
 public function store(Request $r){$this->authorizeManager($r);$d=$r->validate(['name'=>'required|string|max:190','email'=>'nullable|email|max:190|unique:users,email','phone'=>'nullable|string|max:30','password'=>'required|string|min:8|max:100','student_number'=>'nullable|string|max:60','national_id'=>'nullable|string|max:60','birth_date'=>'nullable|date','gender'=>'nullable|in:male,female','address'=>'nullable|string|max:255','admission_date'=>'nullable|date','notes'=>'nullable|string','classroom_id'=>'nullable|integer|exists:classrooms,id']);return DB::transaction(function()use($d){$school=CurrentSchool::id();$user=User::create(['name'=>$d['name'],'email'=>$d['email']??null,'phone'=>$d['phone']??null,'password'=>Hash::make($d['password']),'role'=>'student','is_active'=>true]);$profile=StudentProfile::create(['school_id'=>$school,'user_id'=>$user->id,'student_number'=>$d['student_number']??('STU-'.now()->format('ym').'-'.str_pad((string)$user->id,5,'0',STR_PAD_LEFT)),'national_id'=>$d['national_id']??null,'birth_date'=>$d['birth_date']??null,'gender'=>$d['gender']??null,'address'=>$d['address']??null,'admission_date'=>$d['admission_date']??now()->toDateString(),'notes'=>$d['notes']??null]);if(!empty($d['classroom_id'])){$c=Classroom::where('school_id',$school)->findOrFail($d['classroom_id']);StudentEnrollment::create(['school_id'=>$school,'student_profile_id'=>$profile->id,'classroom_id'=>$c->id,'academic_year_id'=>$c->academic_year_id,'status'=>'active','enrolled_at'=>now()->toDateString()]);}return response()->json(['message'=>'تم إنشاء حساب الطالب بنجاح.','student'=>$profile->load('user','enrollments.classroom')],201);});}
 public function show(Request $r,int $id){$this->authorizeManager($r);return StudentProfile::with(['user','enrollments.classroom.grade'])->where('school_id',CurrentSchool::id())->findOrFail($id);}
 public function update(Request $r,int $id){$this->authorizeManager($r);$p=StudentProfile::where('school_id',CurrentSchool::id())->with('user')->findOrFail($id);$d=$r->validate(['name'=>'sometimes|required|string|max:190','email'=>['nullable','email','max:190',Rule::unique('users','email')->ignore($p->user_id)],'phone'=>'nullable|string|max:30','student_number'=>['sometimes','required','string','max:60',Rule::unique('student_profiles','student_number')->ignore($p->id)],'national_id'=>'nullable|string|max:60','birth_date'=>'nullable|date','gender'=>'nullable|in:male,female','address'=>'nullable|string|max:255','admission_date'=>'nullable|date','notes'=>'nullable|string','status'=>'sometimes|in:active,suspended,archived']);return DB::transaction(function()use($p,$d){$p->update(collect($d)->only(['student_number','national_id','birth_date','gender','address','admission_date','notes','status'])->all());$p->user->update(collect($d)->only(['name','email','phone'])->all());if(($d['status']??null)==='archived')$p->user->update(['is_active'=>false]);return response()->json(['message'=>'تم تحديث بيانات الطالب.','student'=>$p->fresh()->load('user')]);});}
 public function destroy(Request $r,int $id){$this->authorizeManager($r);$p=StudentProfile::where('school_id',CurrentSchool::id())->with('user')->findOrFail($id);$p->update(['status'=>'archived']);$p->user->update(['is_active'=>false]);return response()->json(['message'=>'تمت أرشفة الطالب دون حذف سجله الأكاديمي.']);}
}
